// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount) public {
        vm.assume(caller != address(0) && caller != address(this));
        vm.assume(depositAmount > 0 && depositAmount < 1e18);
        vm.deal(caller, 1e23);

        vm.prank(caller);
        uint256 balanceBefore = address(c).balance;
        c.deposit{value: depositAmount}();
        uint256 balanceAfter = address(c).balance;

        assertTrue(balanceAfter == balanceBefore + depositAmount);
    }
}

